export function uniqueWords(text) {
  const words = text.toLowerCase().match(/\S+/gu) ?? [];
  return [...new Set(words)];
}

originalTest:
import assert from 'node:assert/strict';
import * as m from './solution.mjs';
assert.deepEqual(m.uniqueWords("Hello hello WORLD world"), ["hello", "world"]);
assert.deepEqual(m.uniqueWords("  \t\n "), []);
assert.deepEqual(m.uniqueWords("B\na\tb A"), ["b", "a"]);
assert.deepEqual(m.uniqueWords("Hi! hi hi!"), ["hi!", "hi"]);
